import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { FaArrowRight } from 'react-icons/fa';
import './AgeSelection.css';

function AgeSelection({ userData, setUserData }) {
  const navigate = useNavigate();
  const [name, setName] = useState(userData.name || '');
  const [age, setAge] = useState(userData.age || '');

  const handleProceed = () => {
    if (name.trim() && age) {
      setUserData({
        ...userData,
        name: name.trim(),
        age: parseInt(age)
      });
      navigate('/building-selection');
    }
  };

  const ageOptions = Array.from({ length: 100 }, (_, i) => i);

  return (
    <div className="age-selection fade-in">
      <div className="selection-container">
        <div className="form-card">
          <h1>Visitor Information</h1>
          <p>Please provide your details to proceed</p>

          <div className="form-group">
            <label htmlFor="name">Full Name *</label>
            <input
              id="name"
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="Enter your full name"
              className="form-input"
            />
          </div>

          <div className="form-group">
            <label htmlFor="age">Age *</label>
            <select
              id="age"
              value={age}
              onChange={(e) => setAge(e.target.value)}
              className="form-input"
            >
              <option value="">Select your age</option>
              {ageOptions.map((option) => (
                <option key={option} value={option}>
                  {option} years old
                </option>
              ))}
            </select>
          </div>

          <p className="discount-info">
            {age && age < 12 && (
              <span className="discount-badge">✓ You qualify for a 50% child discount!</span>
            )}
          </p>

          <button
            onClick={handleProceed}
            disabled={!name.trim() || !age}
            className="proceed-button"
          >
            <FaArrowRight /> Continue to Facilities
          </button>
        </div>
      </div>
    </div>
  );
}

export default AgeSelection;
